s['popcorn-rhythm']=r'''
const kernels=[];
const scene={init(){for(let i=0;i<54;i++)kernels.push({x:250+rnd(i+1)*500,y:495+rnd(i+61)*65,base:495+rnd(i+61)*65,vy:-(rnd(i+123)*130),vx:(rnd(i+87)-.5)*15,r:10+rnd(i+33)*9,a:rnd(i+3)*TAU,c:i%4});},tap(){for(const k of kernels)if(Math.abs(k.x-(150+state.x*700))<180)k.vy=-250-rnd(k.x)*170;},beat(i){for(let j=0;j<kernels.length;j++)if((state.playing&&state.trackId==='cancan'&&state.strong)||(j+i)%Math.max(2,Math.round(13-(state.tempo-64)/10))===0)kernels[j].vy=-180-rnd(j+i)*220;},update(dt){for(const k of kernels){k.vy+=dt*540;k.y+=k.vy*dt;k.x+=k.vx*dt;k.a+=dt*k.vy*.003;if(k.y>k.base){k.y=k.base;k.vy=-Math.abs(k.vy)*.24;}if(k.x<230||k.x>770)k.vx*=-1;}},draw(){circle(785,145,50,C[1]);line([[785,75],[785,57]],C[1],3);line([[851,145],[870,145]],C[1],3);ellipse(500,548,353,103,C[0]);ellipse(500,533,328,82,'#eab849');ellipse(500,523,302,65,'#f8f0d9');for(const k of [...kernels].sort((a,b)=>a.y-b.y)){ctx.save();ctx.translate(k.x,k.y);ctx.rotate(k.a);circle(-k.r*.45,0,k.r*.67,C[k.c===0?1:3]);circle(k.r*.4,-k.r*.25,k.r*.74,'#fff8df');circle(0,k.r*.5,k.r*.73,'#f5e6b5');circle(0,0,k.r*.43,'#fffae8');circle(-3,3,2,'#c5a14c');ctx.restore();}text('A VERY ORDINARY AFTERNOON, POPPED',500,655,11,INK+'80');}};
'''
