s['canon-ripples']=r'''
const sources=[[280,325],[525,270],[710,425]],rings=[];
const scene={reset(){rings.length=0;},init(){for(let v=0;v<3;v++)for(let k=0;k<4;k++)rings.push({v,age:k*.7+v*.25});},voice(v){rings.push({v,age:0});if(rings.length>36)rings.shift();},beat(i){if(!state.playing)scene.voice(i%3);},tap(){let pos=[100+state.x*800,100+state.y*500],near=0,d=Infinity;sources.forEach(([x,y],i)=>{let a=Math.hypot(x-pos[0],y-pos[1]);if(a<d){d=a;near=i;}});sources[near]=pos;scene.voice(near);},update(dt){for(const r of rings)r.age+=dt;rings.splice(0,rings.length,...rings.filter(r=>r.age<3.8));},draw(){ctx.save();ctx.globalCompositeOperation='multiply';for(const r of rings){let [x,y]=sources[r.v],radius=20+290*(1-Math.exp(-r.age*.7)),alpha=Math.max(0,1-r.age/3.8);ctx.lineWidth=12*alpha+1;circle(x,y,radius,null,C[r.v]+Math.round(alpha*180).toString(16).padStart(2,'0'));ctx.lineWidth=1;circle(x,y,radius+12,null,C[r.v]+'25');}ctx.restore();sources.forEach(([x,y],v)=>{circle(x,y,19,C[v]);circle(x-5,y-5,4,'#fff8e6');text(['I / NOW','II / LATER','III / AGAIN'][v],x,y+46,10,C[v]);});text('THE SAME MELODY, THREE DIFFERENT ARRIVALS',500,640,11,INK+'80');}};
'''
